#!/usr/bin/env python3
import curses
import subprocess
import sys
import os
import re

class App:
    def __init__(self, stdscr):
        self.stdscr = stdscr
        self.views = []
        self.init_colors()
        curses.curs_set(0)

    def init_colors(self):
        curses.start_color()
        curses.use_default_colors()
        curses.init_pair(1, curses.COLOR_BLUE, -1)    # Date
        curses.init_pair(2, curses.COLOR_GREEN, -1)   # Author
        curses.init_pair(3, curses.COLOR_BLUE, -1)    # Graph node
        curses.init_pair(4, curses.COLOR_WHITE, curses.COLOR_BLUE) # Status bar
        curses.init_pair(5, curses.COLOR_WHITE, curses.COLOR_GREEN) # Selection
        curses.init_pair(6, curses.COLOR_CYAN, -1)    # Headings / branch
        curses.init_pair(7, curses.COLOR_MAGENTA, -1) # Modified / diff @@
        curses.init_pair(8, curses.COLOR_RED, -1)     # Deletions
        curses.init_pair(9, curses.COLOR_YELLOW, -1)  # Date in diff/log
        curses.init_pair(10, curses.COLOR_GREEN, -1)  # Additions

    def push_view(self, view):
        self.views.append(view)

    def pop_view(self):
        if len(self.views) > 1:
            self.views.pop()
        else:
            sys.exit(0)

    def run(self):
        while True:
            if not self.views: break
            current_view = self.views[-1]
            current_view.draw()
            key = self.stdscr.getch()
            if key == curses.KEY_RESIZE:
                for v in self.views:
                    v.update_size()
            else:
                current_view.handle_key(key)

class View:
    def __init__(self, stdscr, app):
        self.stdscr = stdscr
        self.app = app
        self.offset = 0
        self.selected = 0
        self.lines = []
        self.update_size()

    def update_size(self):
        self.height, self.width = self.stdscr.getmaxyx()

    def draw_status_line(self, view_name, info):
        attr = curses.color_pair(4) | curses.A_BOLD
        percent = "100%"
        status_text = f"[{view_name}] {info}"
        status_text = status_text.ljust(self.width - 7) + percent.rjust(6)
        try:
            self.stdscr.addstr(self.height - 1, 0, status_text[:self.width-1], attr)
        except: pass

    def handle_key(self, key):
        if key == ord('q'):
            self.app.pop_view()
        elif key == curses.KEY_UP or key == ord('k'):
            if self.selected > 0:
                self.selected -= 1
                if self.selected < self.offset:
                    self.offset = self.selected
        elif key == curses.KEY_DOWN or key == ord('j'):
            if self.selected < len(self.lines) - 1:
                self.selected += 1
                if self.selected >= self.offset + self.height - 1:
                    self.offset = self.selected - (self.height - 2)
        elif key == curses.KEY_NPAGE:
            self.selected = min(len(self.lines) - 1, self.selected + self.height - 2)
            self.offset = min(max(0, len(self.lines) - (self.height - 1)), self.offset + self.height - 2)
        elif key == curses.KEY_PPAGE:
            self.selected = max(0, self.selected - (self.height - 2))
            self.offset = max(0, self.offset - (self.height - 2))
        elif key == ord('s'):
            self.app.push_view(StatusView(self.stdscr, self.app))
        elif key == ord('m'):
            self.app.push_view(MainView(self.stdscr, self.app))
        elif key == ord('l'):
            self.app.push_view(LogView(self.stdscr, self.app))

class MainView(View):
    def __init__(self, stdscr, app, args=[]):
        super().__init__(stdscr, app)
        self.args = args
        self.load()

    def load(self):
        cmd = ['git', 'log', '--pretty=format:%H%x00%ad%x00%an%x00%s', '--date=format:%Y-%m-%d %H:%M %z'] + self.args
        try:
            output = subprocess.check_output(cmd, stderr=subprocess.DEVNULL).decode('utf-8', errors='replace')
        except:
            output = ""
        self.commits = []
        for line in output.splitlines():
            parts = line.split('\x00')
            if len(parts) == 4:
                self.commits.append({'hash': parts[0], 'date': parts[1], 'author': parts[2], 'subject': parts[3]})

        # Check for changes
        status = subprocess.check_output(['git', 'status', '--porcelain']).decode('utf-8', errors='replace')
        if status:
            staged = any(line[0] in 'MARC' for line in status.splitlines())
            unstaged = any(line[1] in 'M' or line[0] == '?' for line in status.splitlines())

            if unstaged:
                self.commits.insert(0, {'hash': '0'*40, 'date': 'Not Committed Yet', 'author': '', 'subject': 'Unstaged changes', 'special': 'unstaged'})
            if staged:
                self.commits.insert(0, {'hash': '0'*40, 'date': 'Not Committed Yet', 'author': '', 'subject': 'Staged changes', 'special': 'staged'})

        self.lines = self.commits

    def draw(self):
        self.stdscr.clear()
        self.update_size()
        for i in range(self.height - 1):
            idx = i + self.offset
            if idx >= len(self.commits): break
            c = self.commits[idx]
            attr = 0
            if idx == self.selected:
                attr = curses.color_pair(5) | curses.A_BOLD
                line = f"{c['date'][:25].ljust(25)} {c['author'][:15].ljust(15)} o {c['subject']}"
                self.stdscr.addstr(i, 0, line.ljust(self.width-1)[:self.width-1], attr)
            else:
                self.stdscr.addstr(i, 0, c['date'][:25].ljust(25), curses.color_pair(1))
                self.stdscr.addstr(i, 26, c['author'][:15].ljust(15), curses.color_pair(2))
                self.stdscr.addstr(i, 42, "o", curses.color_pair(3))
                self.stdscr.addstr(i, 44, c['subject'][:self.width-45])

        info = self.commits[self.selected]['hash'] if self.commits else ""
        if self.commits and 'special' in self.commits[self.selected]:
            info = self.commits[self.selected]['subject']
        self.draw_status_line("main", info)
        self.stdscr.refresh()

    def handle_key(self, key):
        if key == 10: # Enter
            c = self.commits[self.selected]
            if 'special' not in c:
                self.app.push_view(DiffView(self.stdscr, self.app, [c['hash']]))
            elif c['special'] == 'unstaged':
                self.app.push_view(StatusView(self.stdscr, self.app))
        else:
            super().handle_key(key)

class StatusView(View):
    def __init__(self, stdscr, app):
        super().__init__(stdscr, app)
        self.load()

    def load(self):
        output = subprocess.check_output(['git', 'status']).decode('utf-8', errors='replace')
        self.lines = output.splitlines()

    def draw(self):
        self.stdscr.clear()
        self.update_size()
        for i in range(self.height - 1):
            idx = i + self.offset
            if idx >= len(self.lines): break
            line = self.lines[idx]
            attr = 0
            if idx == self.selected:
                attr = curses.color_pair(5) | curses.A_BOLD
                self.stdscr.addstr(i, 0, line.ljust(self.width-1)[:self.width-1], attr)
            else:
                if line.startswith('Changes to be committed:') or line.startswith('Changes not staged for commit:') or line.startswith('Untracked files:'):
                    self.stdscr.addstr(i, 0, line[:self.width-1], curses.color_pair(6))
                elif line.strip().startswith('modified:'):
                    self.stdscr.addstr(i, 0, line[:self.width-1], curses.color_pair(7))
                else:
                    self.stdscr.addstr(i, 0, line[:self.width-1])
        self.draw_status_line("status", "")
        self.stdscr.refresh()

    def handle_key(self, key):
        if key == ord('u'):
            # Toggle staging - this is simplified
            line = self.lines[self.selected].strip()
            if 'modified:' in line:
                file = line.split(':')[-1].strip()
                # Check if staged or not
                # This is a very simplified version
                subprocess.run(['git', 'add', file]) # Or reset
                self.load()
        else:
            super().handle_key(key)

class DiffView(View):
    def __init__(self, stdscr, app, args):
        super().__init__(stdscr, app)
        self.args = args
        self.load()

    def load(self):
        cmd = ['git', 'show', '--patch-with-stat'] + self.args
        self.lines = subprocess.check_output(cmd).decode('utf-8', errors='replace').splitlines()

    def draw(self):
        self.stdscr.clear()
        self.update_size()
        for i in range(self.height - 1):
            idx = i + self.offset
            if idx >= len(self.lines): break
            line = self.lines[idx]
            attr = 0
            if idx == self.selected:
                attr = curses.color_pair(5) | curses.A_BOLD
                self.stdscr.addstr(i, 0, line.ljust(self.width-1)[:self.width-1], attr)
            else:
                if line.startswith('commit '):
                    self.stdscr.addstr(i, 0, line[:self.width-1], curses.color_pair(2))
                elif line.startswith('Author: '):
                    self.stdscr.addstr(i, 0, line[:self.width-1], curses.color_pair(6))
                elif line.startswith('Date: '):
                    self.stdscr.addstr(i, 0, line[:self.width-1], curses.color_pair(9))
                elif line.startswith('+'):
                    self.stdscr.addstr(i, 0, line[:self.width-1], curses.color_pair(10))
                elif line.startswith('-'):
                    self.stdscr.addstr(i, 0, line[:self.width-1], curses.color_pair(8))
                elif line.startswith('@@'):
                    self.stdscr.addstr(i, 0, line[:self.width-1], curses.color_pair(7))
                else:
                    self.stdscr.addstr(i, 0, line[:self.width-1])
        self.draw_status_line("diff", " ".join(self.args))
        self.stdscr.refresh()

class LogView(DiffView):
    def load(self):
        cmd = ['git', 'log', '--stat'] + self.args
        self.lines = subprocess.check_output(cmd).decode('utf-8', errors='replace').splitlines()
    def draw(self):
        super().draw()
        self.draw_status_line("log", " ".join(self.args))

class PagerView(View):
    def __init__(self, stdscr, app, input_data):
        super().__init__(stdscr, app)
        self.lines = input_data.splitlines()
    def draw(self):
        self.stdscr.clear()
        self.update_size()
        for i in range(self.height - 1):
            idx = i + self.offset
            if idx >= len(self.lines): break
            line = self.lines[idx]
            if idx == self.selected:
                self.stdscr.addstr(i, 0, line.ljust(self.width-1)[:self.width-1], curses.color_pair(5) | curses.A_BOLD)
            else:
                # Colorize pager output (similar to diff)
                if line.startswith('+'): self.stdscr.addstr(i, 0, line[:self.width-1], curses.color_pair(10))
                elif line.startswith('-'): self.stdscr.addstr(i, 0, line[:self.width-1], curses.color_pair(8))
                else: self.stdscr.addstr(i, 0, line[:self.width-1])
        self.draw_status_line("pager", "")
        self.stdscr.refresh()

def main_wrapper(stdscr):
    app = App(stdscr)
    args = sys.argv[1:]
    if not sys.stdin.isatty():
        input_data = sys.stdin.read()
        # If we are piped, we might still want to open a terminal for the TUI
        # This is tricky in Python. Tig handles this by reopening /dev/tty.
        sys.stdin = open('/dev/tty', 'r')
        app.push_view(PagerView(stdscr, app, input_data))
    elif not args:
        app.push_view(MainView(stdscr, app))
    elif args[0] == 'status':
        app.push_view(StatusView(stdscr, app))
    elif args[0] == 'log':
        app.push_view(MainView(stdscr, app, args[1:])) # Tig log is often similar to main but with different options
    elif args[0] == 'show':
        app.push_view(DiffView(stdscr, app, args[1:]))
    elif args[0] == 'blame':
        # Simple placeholder for blame
        app.push_view(PagerView(stdscr, app, subprocess.check_output(['git', 'blame'] + args[1:]).decode('utf-8')))
    else:
        # Fallback to MainView with args
        app.push_view(MainView(stdscr, app, args))

    app.run()

if __name__ == '__main__':
    try:
        curses.wrapper(main_wrapper)
    except KeyboardInterrupt:
        pass
