    def __init__(self, stdscr, app):
        self.stdscr = stdscr
        self.app = app
        self.offset = 0
        self.selected = 0
        self.lines = []
        self.update_size()

    def update_size(self):
        self.height, self.width = self.stdscr.getmaxyx()

    def draw_status_line(self, view_name, info):
        attr = curses.color_pair(4) | curses.A_BOLD
        percent = "100%"
        status_text = f"[{view_name}] {info}"
        status_text = status_text.ljust(self.width - 7) + percent.rjust(6)
        try:
            self.stdscr.addstr(self.height - 1, 0, status_text[:self.width-1], attr)
        except: pass

    def handle_key(self, key):
        if key == ord('q'):
            self.app.pop_view()
        elif key == curses.KEY_UP or key == ord('k'):
            if self.selected > 0:
                self.selected -= 1
                if self.selected < self.offset:
                    self.offset = self.selected
        elif key == curses.KEY_DOWN or key == ord('j'):
            if self.selected < len(self.lines) - 1:
                self.selected += 1
                if self.selected >= self.offset + self.height - 1:
                    self.offset = self.selected - (self.height - 2)
        elif key == curses.KEY_NPAGE or key == ord(' '):
            step = self.height - 2
            self.selected = min(len(self.lines) - 1, self.selected + step)
            self.offset = min(max(0, len(self.lines) - (self.height - 1)), self.offset + step)
        elif key == curses.KEY_PPAGE:
            step = self.height - 2
            self.selected = max(0, self.selected - step)
            self.offset = max(0, self.offset - step)
        elif key == ord('s'):
            self.app.push_view(StatusView(self.stdscr, self.app))
        elif key == ord('m'):
            self.app.push_view(MainView(self.stdscr, self.app))
        elif key == ord('l'):
            self.app.push_view(DiffView(self.stdscr, self.app, [], "log"))
        elif key == ord('r'):
            self.app.push_view(RefsView(self.stdscr, self.app))
        elif key == ord('h'):
            self.app.push_view(HelpView(self.stdscr, self.app))

