        self.lines.append("Changes to be committed:")
        if staged:
            for l in staged: self.lines.append(f"  {l[0]} {l[3:]}")
        else: self.lines.append("  (no files)")
        unstaged = [l for l in status if l[1] in 'M' or l[0:2] == '??']
        self.lines.append("Changes not staged for commit:")
        if unstaged:
            for l in [l for l in status if l[1] == 'M']: self.lines.append(f"  M {l[3:]}")
            for l in [l for l in status if l[0:2] == '??']: self.lines.append(f"  ? {l[3:]}")
        else: self.lines.append("  (no files)")
        untracked = [l for l in status if l[0:2] == '??']
        self.lines.append("Untracked files:")
