                elif line.startswith('+') and not line.startswith('+++'): self.stdscr.addstr(i, 0, line[:self.width-1], curses.color_pair(10))
                elif line.startswith('-') and not line.startswith('---'): self.stdscr.addstr(i, 0, line[:self.width-1], curses.color_pair(8))
                elif line.startswith('@@'): self.stdscr.addstr(i, 0, line[:self.width-1], curses.color_pair(7))
                else: self.stdscr.addstr(i, 0, line[:self.width-1])
        self.draw_status_line(self.view_name, " ".join(self.args))
        self.stdscr.refresh()

class RefsView(View):
    def __init__(self, stdscr, app):
        super().__init__(stdscr, app)
        self.lines = run_git(['show-ref']).splitlines()
    def draw(self):
        self.stdscr.clear()
        self.update_size()
        for i in range(self.height - 1):
            idx = i + self.offset
            if idx >= len(self.lines): break
            line = self.lines[idx]
            if idx == self.selected: self.stdscr.addstr(i, 0, line.ljust(self.width-1)[:self.width-1], curses.color_pair(5) | curses.A_BOLD)
            else: self.stdscr.addstr(i, 0, line[:self.width-1], curses.color_pair(6))
        self.draw_status_line("refs", "")
        self.stdscr.refresh()

class HelpView(View):
    def __init__(self, stdscr, app):
        super().__init__(stdscr, app)
        self.lines = [
            "Quick reference for tig keybindings:",
            "  m view-main          Show main view",
            "  d view-diff          Show diff view",
