        self.update_size()
        for i in range(self.height - 1):
            idx = i + self.offset
            if idx >= len(self.lines): break
            line = self.lines[idx]
            if idx == self.selected: self.stdscr.addstr(i, 0, line.ljust(self.width-1)[:self.width-1], curses.color_pair(5) | curses.A_BOLD)
