        self.draw_status_line("help", "")
        self.stdscr.refresh()

def main_wrapper(stdscr):
    app = App(stdscr)
    args = sys.argv[1:]

    # Handle -C
    if '-C' in args:
        idx = args.index('-C')
        if idx + 1 < len(args):
            os.chdir(args[idx+1])
            del args[idx:idx+2]

    if not sys.stdin.isatty():
        data = sys.stdin.read()
        try: sys.stdin = open('/dev/tty', 'r')
        except: pass
        view = DiffView(stdscr, app, [], "pager")
        view.lines = data.splitlines()
        app.push_view(view)
    elif not args: app.push_view(MainView(stdscr, app))
    elif args[0] == 'status': app.push_view(StatusView(stdscr, app))
    elif args[0] == 'log': app.push_view(DiffView(stdscr, app, args[1:], "log"))
    elif args[0] == 'show': app.push_view(DiffView(stdscr, app, args[1:], "diff"))
    elif args[0] == 'blame': app.push_view(DiffView(stdscr, app, args[1:], "blame"))
    elif args[0] == 'grep': app.push_view(DiffView(stdscr, app, args[1:], "grep"))
    elif args[0] == 'refs': app.push_view(RefsView(stdscr, app))
    elif args[0] == 'stash':
        view = DiffView(stdscr, app, [], "stash")
        view.lines = run_git(['stash', 'list']).splitlines()
        app.push_view(view)
    else: app.push_view(MainView(stdscr, app, args))
    app.run()

if __name__ == '__main__':
    if '-v' in sys.argv or '--version' in sys.argv:
        print("tig version 2.6.0-g87c9c25")
        print("ncursesw version 6.3.20211021")
        sys.exit(0)
    if '-h' in sys.argv or '--help' in sys.argv:
        print("Usage: tig [options] [revs] [--] [paths]")
        print("   or: tig status")
        sys.exit(0)
    try: curses.wrapper(main_wrapper)
    except KeyboardInterrupt: pass
